def generate_signals(df: pd.DataFrame) -> pd.Series:
    ma = df['close'].rolling(window=20).mean()
    std = df['close'].rolling(window=20).std()
    upper = ma + 2 * std

    signal = pd.Series(0, index=df.index)
    in_position = False
    for i in range(len(df)):
        if pd.isna(ma.iloc[i]):
            continue
        if not in_position and df['close'].iloc[i] > upper.iloc[i]:
            in_position = True
            signal.iloc[i] = 1
        elif in_position and df['close'].iloc[i] <= ma.iloc[i]:
            in_position = False
            signal.iloc[i] = 0
    return signal

def generate_signals(df: pd.DataFrame) -> pd.Series:
    close = df['close'].values
    n = len(close)
    signals = np.zeros(n, dtype=int)

    ma_window = 200
    ma = pd.Series(close).rolling(window=ma_window).mean().values

    in_pos = False
    peak = 0.0

    for i in range(n):
        if i < ma_window - 1:
            continue

        if not in_pos:
            if close[i] > ma[i]:
                signals[i] = 1
                in_pos = True
                peak = close[i]
        else:
            if close[i] > peak:
                peak = close[i]

            if (peak - close[i]) / peak >= 0.20 or close[i] < ma[i]:
                signals[i] = 0
                in_pos = False
                peak = 0.0
            else:
                signals[i] = 1

    return pd.Series(signals, index=df.index)

def generate_signals(df: pd.DataFrame) -> pd.Series:
    window = 20
    std_mult = 2
    sma = df['close'].rolling(window=window).mean()
    std = df['close'].rolling(window=window).std()
    lower = sma - std_mult * std
    middle = sma

    signals = pd.Series(0, index=df.index)
    position = 0

    for i in range(len(df)):
        if position == 0:
            if df['close'].iloc[i] < lower.iloc[i]:
                signals.iloc[i] = 1
                position = 1
        else:
            if df['close'].iloc[i] >= middle.iloc[i]:
                signals.iloc[i] = 0
                position = 0
    return signals

def generate_signals(df: pd.DataFrame) -> pd.Series:
    ma20 = df['close'].rolling(window=20).mean()
    delta = df['close'].diff()
    up = delta.clip(lower=0)
    down = delta.clip(upper=0).abs()
    avg_up = up.rolling(6).mean()
    avg_down = down.rolling(6).mean()
    rs = avg_up / avg_down.clip(lower=1e-10)
    rsi = 100 - (100 / (1 + rs))

    signals = pd.Series(0, index=df.index)
    in_pos = False

    for i in range(len(df)):
        if in_pos:
            if df['close'].iloc[i] >= ma20.iloc[i]:
                signals.iloc[i] = 0
                in_pos = False
            else:
                signals.iloc[i] = 1
        else:
            if rsi.iloc[i] < 30:
                signals.iloc[i] = 1
                in_pos = True
            else:
                signals.iloc[i] = 0
    return signals

